BEGIN;
CREATE TEMP TABLE _col_antes ON COMMIT DROP AS
SELECT c.relname, a.attname, r.rolname, x.privilege_type
  FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace
  CROSS JOIN LATERAL aclexplode(a.attacl) x JOIN pg_roles r ON r.oid = x.grantee
 WHERE n.nspname = 'public' AND a.attnum > 0 AND NOT a.attisdropped AND r.rolname IN ('anon','authenticated');
CREATE TEMP TABLE _sr_antes ON COMMIT DROP AS
SELECT p.oid, has_function_privilege('service_role', p.oid, 'EXECUTE') AS pode
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public';
DO $$ BEGIN
  IF (SELECT count(DISTINCT (relname, attname)) FROM _col_antes) <> 37 THEN
    RAISE EXCEPTION 'esperava 37 colunas com grant proprio'; END IF;
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
              WHERE n.nspname = 'public' AND pg_get_userbyid(p.proowner) <> 'postgres') THEN
    RAISE EXCEPTION 'ha funcao de public cujo dono nao e postgres'; END IF;
END $$;
