-- 3) Reaplica a fotografia dos grants de coluna
DO $$ DECLARE g record; BEGIN
  FOR g IN SELECT * FROM _col_antes LOOP
    EXECUTE format('GRANT %s (%I) ON public.%I TO %I', g.privilege_type, g.attname, g.relname, g.rolname);
  END LOOP; END $$;
-- 4) Conferencias: qualquer falha desfaz a transacao inteira
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM (
    SELECT * FROM _col_antes EXCEPT
    SELECT c.relname, a.attname, r.rolname, x.privilege_type
      FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace ns ON ns.oid = c.relnamespace
      CROSS JOIN LATERAL aclexplode(a.attacl) x JOIN pg_roles r ON r.oid = x.grantee
     WHERE ns.nspname = 'public' AND a.attnum > 0 AND NOT a.attisdropped AND r.rolname IN ('anon','authenticated')) d;
  IF n <> 0 THEN RAISE EXCEPTION 'grant de coluna perdido: %', n; END IF;
  SELECT count(*) INTO n FROM _sr_antes s WHERE has_function_privilege('service_role', s.oid, 'EXECUTE') IS DISTINCT FROM s.pode;
  IF n <> 0 THEN RAISE EXCEPTION 'service_role mudou em % funcoes', n; END IF;
  SELECT count(*) INTO n FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace WHERE ns.nspname = 'public' AND has_function_privilege('anon', p.oid, 'EXECUTE');
  IF n <> 27 THEN RAISE EXCEPTION 'anon executa % (esperado 27, igual a Savy)', n; END IF;
  SELECT count(*) INTO n FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace WHERE ns.nspname = 'public' AND has_function_privilege('authenticated', p.oid, 'EXECUTE');
  IF n <> 95 THEN RAISE EXCEPTION 'authenticated executa % (esperado 95, igual a Savy)', n; END IF;
  IF NOT has_column_privilege('anon', 'public.config_pagamento_cartao', 'credito', 'SELECT')
     OR NOT has_column_privilege('authenticated', 'public.config_pagamento_cartao', 'credito', 'SELECT') THEN
    RAISE EXCEPTION 'cartao sumiria do checkout'; END IF;
  IF NOT has_column_privilege('authenticated', 'public.produtos', 'imagem_url', 'SELECT') THEN
    RAISE EXCEPTION 'Meus pedidos quebraria'; END IF;
  IF has_column_privilege('anon', 'public.produtos', 'custo', 'SELECT')
     OR has_column_privilege('authenticated', 'public.produtos', 'custo', 'SELECT') THEN
    RAISE EXCEPTION 'custo continuaria legivel'; END IF;
  IF NOT has_column_privilege('authenticated', 'public.marketplace_orders', 'tracking_code', 'UPDATE')
     OR has_column_privilege('authenticated', 'public.marketplace_orders', 'status', 'UPDATE') THEN
    RAISE EXCEPTION 'UPDATE de pedido errado'; END IF;
  IF has_function_privilege('anon', 'public.confirmar_pagamento(uuid,text,text)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.confirmar_pagamento(uuid,text,text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'confirmar_pagamento aberto'; END IF;
  IF NOT has_function_privilege('service_role', 'public.confirmar_pagamento(uuid,text,text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'webhook perderia a confirmacao'; END IF;
  IF NOT has_function_privilege('anon', 'public.create_marketplace_order_v24(jsonb,numeric,numeric,text,uuid,text,text,text,text,jsonb,text,text,uuid)', 'EXECUTE') THEN
    RAISE EXCEPTION 'checkout de convidado fecharia'; END IF;
END $$;
